package com.jnapanam.sportszone.training.controller;import com.jnapanam.sportszone.training.dto.*;import com.jnapanam.sportszone.training.service.TrainingService;import jakarta.validation.Valid;import java.util.*;import org.springframework.http.*;import org.springframework.security.access.prepost.PreAuthorize;import org.springframework.web.bind.annotation.*;@RestController@RequestMapping("/api/v1/admin/training")@PreAuthorize("hasAnyRole('SUPER_ADMIN','ADMIN','OPERATIONS')")public class AdminTrainingController{private final TrainingService s;public AdminTrainingController(TrainingService s){this.s=s;}@GetMapping("/programs")public List<ProgramResponse>programs(){return s.allPrograms();}@PostMapping("/programs")@ResponseStatus(HttpStatus.CREATED)public ProgramResponse createProgram(@Valid@RequestBody ProgramRequest r){return s.createProgram(r);}@PutMapping("/programs/{id}")public ProgramResponse updateProgram(@PathVariable UUID id,@Valid@RequestBody ProgramRequest r){return s.updateProgram(id,r);}@PatchMapping("/programs/{id}/status")public ProgramResponse programStatus(@PathVariable UUID id,@Valid@RequestBody TrainingStatusRequest r){return s.programStatus(id,r);}@GetMapping("/batches")public List<BatchResponse>batches(){return s.allBatches();}@PostMapping("/batches")@ResponseStatus(HttpStatus.CREATED)public BatchResponse createBatch(@Valid@RequestBody BatchRequest r){return s.createBatch(r);}@PutMapping("/batches/{id}")public BatchResponse updateBatch(@PathVariable UUID id,@Valid@RequestBody BatchRequest r){return s.updateBatch(id,r);}@PatchMapping("/batches/{id}/status")public BatchResponse batchStatus(@PathVariable UUID id,@Valid@RequestBody TrainingStatusRequest r){return s.batchStatus(id,r);}@GetMapping("/batches/{id}/participants")public List<EnrollmentResponse>roster(@PathVariable UUID id){return s.roster(id);}@PutMapping("/enrollments/{id}/attendance")@ResponseStatus(HttpStatus.NO_CONTENT)public void attendance(@PathVariable UUID id,@Valid@RequestBody AttendanceRequest r){s.attendance(id,r);}}
